    int lines = 0, words = 0;
    unsigned long bytes = 0;
    size_t max_len = 0, line_bytes = 0;
    int in_word = 0;
    int c;

    while ((c = fgetc(stdin)) != EOF) {
        unsigned char by = (unsigned char)c;
        bytes++;
        line_bytes++;

