            if (!in_word && bytes > 1) {
                if (line_bytes > max_len)
                    max_len = line_bytes;
                in_word = 1;
            }
            words += !!in_word;
        } else {
            if (by == '\n') {
                lines++;
                if (line_bytes > max_len)
                    max_len = line_bytes;
                in_word = 0;
                line_bytes = 0;
            } else {
                if (line_bytes > max_len)
                    max_len = line_bytes;
                in_word = 0;
                line_bytes = 0;
            }
        }
    }

    if (bytes == 0)
        return (lines == 0 && words == 0 && max_len == 0) ? 0 : 1;

    if (line_bytes > max_len)
